package java.lang.reflect;
public final class Modifier { public static final int PUBLIC=1,PRIVATE=2,PROTECTED=4,STATIC=8,FINAL=16,ABSTRACT=1024,INTERFACE=512; public static boolean isPublic(int m){return (m&PUBLIC)!=0;} public static boolean isPrivate(int m){return (m&PRIVATE)!=0;} public static boolean isProtected(int m){return (m&PROTECTED)!=0;} public static boolean isStatic(int m){return (m&STATIC)!=0;} public static boolean isFinal(int m){return (m&FINAL)!=0;} public static boolean isAbstract(int m){return (m&ABSTRACT)!=0;} public static boolean isInterface(int m){return (m&INTERFACE)!=0;} }
